#include "apex/tracking.hpp"
#include <nlohmann/json.hpp>
#include <algorithm>
#include <cmath>
#include <fstream>
#include <stdexcept>
namespace apex {namespace {
void validate(const TrackingOptions& o){auto axis=[](const TrackingAxis& a){return std::isfinite(a.gain)&&a.gain>=0&&a.gain<=10&&std::isfinite(a.smoothingMs)&&a.smoothingMs>=0&&a.smoothingMs<=500&&std::isfinite(a.maxSpeed)&&a.maxSpeed>=10&&a.maxSpeed<=1000;};if(!axis(o.x)||!axis(o.y)||!std::isfinite(o.radius)||o.radius<20||o.radius>800||!std::isfinite(o.deadzone)||o.deadzone<0||o.deadzone>30||!std::isfinite(o.anchor)||o.anchor<.1f||o.anchor>.9f||!std::isfinite(o.maxAgeMs)||o.maxAgeMs<50||o.maxAgeMs>500)throw std::runtime_error("Invalid tracking settings");}
float iou(const EnemyBox& a,const EnemyBox& b){float intersection=std::max(0.f,std::min(a.x2,b.x2)-std::max(a.x1,b.x1))*std::max(0.f,std::min(a.y2,b.y2)-std::max(a.y1,b.y1));float sum=(a.x2-a.x1)*(a.y2-a.y1)+(b.x2-b.x1)*(b.y2-b.y1)-intersection;return sum>0?intersection/sum:0;}
bool validBox(const EnemyBox& b){return std::isfinite(b.x1)&&std::isfinite(b.y1)&&std::isfinite(b.x2)&&std::isfinite(b.y2)&&std::isfinite(b.score)&&b.score>=0&&b.score<=1&&b.x1>=0&&b.y1>=0&&b.x2<=1&&b.y2<=1&&b.x2>b.x1&&b.y2>b.y1;}
int axisStep(float error,const TrackingAxis& axis,float deadzone,float dt,float& velocity,float& remainder){if(!axis.enabled||std::abs(error)<=deadzone){velocity=remainder=0;return 0;}if(velocity*error<0)velocity=remainder=0;float desired=std::clamp(error*axis.gain,-axis.maxSpeed,axis.maxSpeed);float alpha=axis.smoothingMs>0?1-std::exp(-dt*1000/axis.smoothingMs):1;velocity+=(desired-velocity)*alpha;float amount=velocity*dt+remainder;int step=std::clamp(static_cast<int>(amount),-12,12);remainder=std::clamp(amount-step,-1.f,1.f);return step;}
}
void TargetTracker::reset(){locked_=false;lastSequence_=0;lastFrame_=-1;lastTick_=-1;velocityX_=velocityY_=remainderX_=remainderY_=0;}
TrackingResult TargetTracker::update(const std::vector<EnemyBox>& boxes,const TrackingContext& c,const TrackingOptions& o){TrackingResult result;try{validate(o);}catch(const std::exception& e){reset();result.status=e.what();return result;}
 if(!std::isfinite(c.now)||!std::isfinite(c.frameTime)||!std::isfinite(c.width)||!std::isfinite(c.height)||c.width<=0||c.height<=0||c.frameTime<=0){reset();result.status="Waiting for selected game geometry";return result;}
 result.ageMs=float((c.now-c.frameTime)*1000);if(!c.live){reset();result.status="Live camera capture required; no input from recordings";return result;}if(result.ageMs<0||result.ageMs>o.maxAgeMs){reset();result.status="Capture/model result stale; mouse output stopped";return result;}
 bool newFrame=c.sequence!=lastSequence_||c.frameTime!=lastFrame_;if(newFrame){const EnemyBox* selected=nullptr;float bestDistance=o.radius*o.radius,bestOverlap=0;for(const auto& b:boxes){if(!validBox(b))continue;float x=(b.x1+b.x2)*.5f*c.width-c.width*.5f,y=(b.y1+(b.y2-b.y1)*o.anchor)*c.height-c.height*.5f;float distance=x*x+y*y;if(distance>o.radius*o.radius)continue;float overlap=locked_?iou(box_,b):0;if(locked_&&overlap>=.15f){if(overlap>bestOverlap){selected=&b;bestOverlap=overlap;}}else if(bestOverlap==0&&distance<bestDistance){selected=&b;bestDistance=distance;}}
  if(selected){bool continuing=locked_&&iou(box_,*selected)>=.15f;if(!continuing){identity_=nextIdentity_++;velocityX_=velocityY_=remainderX_=remainderY_=0;}box_=*selected;locked_=true;}else locked_=false;lastSequence_=c.sequence;lastFrame_=c.frameTime;}
 if(locked_){result.target=true;result.targetId=identity_;result.x=(box_.x1+box_.x2)*.5f*c.width;result.y=(box_.y1+(box_.y2-box_.y1)*o.anchor)*c.height;result.errorX=result.x-c.width*.5f;result.errorY=result.y-c.height*.5f;if(result.errorX*result.errorX+result.errorY*result.errorY>o.radius*o.radius){locked_=false;result.target=false;}}
 bool engaged=o.armed&&c.focused&&c.hold&&c.emergencyAvailable&&result.target;float dt=lastTick_>=0?float(std::clamp(c.now-lastTick_,0.,.05)):0;lastTick_=c.now;result.engaged=engaged;
 if(!engaged){velocityX_=velocityY_=remainderX_=remainderY_=0;result.status=!o.armed?"Disarmed; configure and explicitly arm":!c.emergencyAvailable?"Emergency hotkey unavailable":!c.focused?"Selected Apex window is not focused":!c.hold?"Hold right mouse button to follow candidates":!result.target?"No candidate inside FOV":"Paused";return result;}
 result.moveX=axisStep(result.errorX,o.x,o.deadzone,dt,velocityX_,remainderX_);result.moveY=axisStep(result.errorY,o.y,o.deadzone,dt,velocityY_,remainderY_);result.status="Following visible model candidate; game input acceptance unverified";return result;
}
bool saveTrackingOptions(const std::filesystem::path& path,const TrackingOptions& o,std::string& error){try{validate(o);auto axis=[](const TrackingAxis& a){return nlohmann::json{{"enabled",a.enabled},{"gain",a.gain},{"smoothing_ms",a.smoothingMs},{"max_speed",a.maxSpeed}};};nlohmann::json j={{"version",1},{"x",axis(o.x)},{"y",axis(o.y)},{"radius",o.radius},{"deadzone",o.deadzone},{"anchor",o.anchor},{"max_age_ms",o.maxAgeMs},{"show_fov",o.showFov}};std::filesystem::create_directories(path.parent_path());std::ofstream f(path);f<<j.dump(2);f.flush();if(!f)throw std::runtime_error("Tracking setup write failed");error.clear();return true;}catch(const std::exception& e){error=e.what();return false;}}
bool loadTrackingOptions(const std::filesystem::path& path,TrackingOptions& o,std::string& error){try{if(std::filesystem::file_size(path)>16384)throw std::runtime_error("Tracking setup too large");nlohmann::json j;std::ifstream(path)>>j;if(j.at("version")!=1)throw std::runtime_error("Unsupported tracking setup");TrackingOptions next;auto axis=[](const nlohmann::json& a){TrackingAxis result;result.enabled=a.at("enabled");result.gain=a.at("gain");result.smoothingMs=a.at("smoothing_ms");result.maxSpeed=a.at("max_speed");return result;};next.x=axis(j.at("x"));next.y=axis(j.at("y"));next.radius=j.at("radius");next.deadzone=j.at("deadzone");next.anchor=j.at("anchor");next.maxAgeMs=j.at("max_age_ms");next.showFov=j.at("show_fov");validate(next);next.armed=false;o=next;error.clear();return true;}catch(const std::exception& e){error=e.what();return false;}}
}
